import urllib.request
import os
import json
import pandas as pd

# Constants
TARGET_JSON_FILE = "downloaded_file.json"


def task_func(url):
    urllib.request.urlretrieve(url, TARGET_JSON_FILE)
    try:
        with open(TARGET_JSON_FILE, "r", encoding="utf-8") as f:
            json_content = json.load(f)

        if isinstance(json_content, list):
            return pd.DataFrame(json_content)

        if isinstance(json_content, dict):
            try:
                return pd.DataFrame(json_content)
            except (ValueError, TypeError):
                return pd.DataFrame([json_content])

        return pd.DataFrame([json_content])
    finally:
        if os.path.exists(TARGET_JSON_FILE):
            try:
                os.remove(TARGET_JSON_FILE)
            except OSError:
                pass
